INSERT INTO `courses` VALUES (1,'Bachelor of Elementary Education (BEEd)','Prepares students to teach in the elementary level.',1,5,'Teacher / Educator, School Administrator, Curriculum Developer, Early Childhood Educator','2026-08-11 13:20:35','','',''),(2,'Bachelor of Secondary Education (BSEd) - Major in English','Prepares students to teach English language and literature in high school.',1,5,'English Language Teacher, College Professor, Curriculum Developer, Journalist / Media Professional','2026-08-11 13:20:35','','',''),(3,'Bachelor of Secondary Education (BSEd) - Major in Filipino','Prepares students to teach Filipino language and literature.',1,5,'Filipino Language Teacher, Teacher / Educator, Curriculum Developer','2026-08-11 13:20:35','','',''),(4,'Bachelor of Secondary Education (BSEd) - Major in Mathematics','Prepares students to teach mathematics at the secondary level.',1,5,'Math Teacher, Teacher / Educator, Curriculum Developer, Mathematician / Statistician','2026-08-11 13:20:35','','',''),(5,'Bachelor of Secondary Education (BSEd) - Major in Science','Prepares students to teach general science in high school.',3,5,'Science Teacher, Teacher / Educator, Curriculum Developer, Researcher / Academic','2026-08-11 13:20:35','','',''),(6,'Bachelor of Secondary Education (BSEd) - Major in Social Studies','Prepares students to teach social science subjects in high school.',1,5,'Social Studies Teacher, Teacher / Educator, Researcher / Academic','2026-08-11 13:20:35','','',''),(7,'Bachelor of Secondary Education (BSEd) - Major in Values Education','Prepares students to teach values education.',1,5,'Teacher / Educator, Social Worker, Theologian / Religious Worker','2026-08-11 13:20:35','','',''),(8,'Bachelor of Secondary Education (BSEd) - Major in Biological Science','Prepares students to teach biological sciences.',3,5,'Science Teacher, Biological Scientist, Researcher / Academic','2026-08-11 13:20:35','','',''),(9,'Bachelor of Secondary Education (BSEd) - Majo