INSERT INTO `questions_personality` VALUES (1,'I enjoy visiting places I\'ve never been to before.','Openness','likert','easy',1,'2026-07-27 09:22:39'),(2,'I like trying foods from cuisines I haven\'t tasted before.','Openness','likert','easy',1,'2026-07-27 09:22:39'),(3,'I often wonder about how things could be different or better.','Openness','likert','easy',1,'2026-07-27 09:22:39'),(4,'I enjoy conversations that challenge how I normally think.','Openness','likert','medium',1,'2026-07-27 09:22:39'),(5,'I like exploring hobbies outside my comfort zone.','Openness','likert','medium',1,'2026-07-27 09:22:39'),(6,'I am drawn to unconventional or experimental approaches.','Openness','likert','medium',1,'2026-07-27 09:22:39'),(7,'I enjoy daydreaming or imagining alternate possibilities.','Openness','likert','medium',1,'2026-07-27 09:22:39'),(8,'I like learning skills that have no immediate practical use, just for curiosity.','Openness','likert','hard',1,'2026-07-27 09:22:39'),(9,'I feel energized by novelty rather than familiarity.','Openness','likert','hard',1,'2026-07-27 09:22:39'),(10,'I actively seek out perspectives different from my own.','Openness','likert','hard',1,'2026-07-27 09:22:39'),(11,'Describe an idea or belief you changed your mind about. What led you to change it?','Openness','open-ended',NULL,1,'2026-07-27 09:22:39'),(12,'If you could learn any new skill purely out of curiosity, what would it be and why?','Openness','open-ended',NULL,1,'2026-07-27 09:22:39'),(13,'I prepare a to-do list before starting my day.','Conscientiousness','likert','easy',1,'2026-07-27 09:22:39'),(14,'I keep track of deadlines well in advance.','Conscientiousness','likert','easy',1,'2026-07-27 09:22:39'),(15,'I finish what I start, even when it gets difficult.','Conscientiousness','likert','easy',1,'2026-07-27 09:22:39'),(16,'I hold myself to high standards in my schoolwork or tasks.','Conscientiousness','likert','medium',1,'2026-07-27 09:22:39'),(17,'I stay focused on a task un