  `school_year_id` int(11) DEFAULT 1,
  `started_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `completed_at` timestamp NULL DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `total_score` decimal(7,2) DEFAULT NULL,
